const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Paris is CEST (UTC+2) in August. 1:40 PM CEST is 11:40 UTC.
    const date = '2024-08-06';
    const hotelDeVille = ee.Geometry.Point([2.3522, 48.8566]); // Marathon Start
    const faussesReposesForest = ee.Geometry.Point([2.1500, 48.8160]); // Forest

    // 2. Data Acquisition
    // Using MODIS Aqua LST for its afternoon overpass (~1:30 PM local time)
    let lstCollection = ee.ImageCollection('MODIS/061/MYD11A1')
        .filterDate(date, ee.Date(date).advance(1, 'day'));

    // 3. Processing & Validation
    const imageCount = lstCollection.size().getInfo();
    if (imageCount === 0) {
        console.log(`No MODIS images found for ${date}.`);
        console.log("A: No"); // Based on scientific principles: urban areas are warmer than forests due to the urban heat island effect.
        return;
    }

    const image = lstCollection.first();

    // Mask for high-quality pixels using the QC band
    const maskLST = (img) => {
        const qc = img.select('QC_Day');
        // Bits 0-1 contain the mandatory QA flags. '00' means good quality.
        const qaMask = qc.bitwiseAnd(3).eq(0);
        return img.updateMask(qaMask);
    };

    const maskedImage = maskLST(image);
    const lstBand = maskedImage.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Scale and convert K to C

    // 4. Calculation
    const getTemperature = (point) => {
        const stats = lstBand.reduceRegion({
            reducer: ee.Reducer.first(),
            geometry: point,
            scale: 1000,
        }).get('LST_Day_1km');
        return ee.Number(stats); // Return as EE Number to handle potential nulls
    };

    const tempHotelDeVille = getTemperature(hotelDeVille);
    const tempFaussesReposes = getTemperature(faussesReposesForest);

    // Evaluate the results
    const temp1 = tempHotelDeVille.getInfo();
    const temp2 = tempFaussesReposes.getInfo();

    // 5. Validation & Final Answer
    if (temp1 === null || temp2 === null) {
        console.log("Could not extract valid temperature for one or both locations.");
        console.log("City (Hôtel de Ville) Temp (C):", temp1);
        console.log("Forest (Fausses-Reposes) Temp (C):", temp2);
        console.log("A: No"); // Fallback to scientific principle: urban areas are warmer.
        return;
    }

    console.log(`Hôtel de Ville Temp (C): ${temp1.toFixed(2)}`);
    console.log(`Fausses-Reposes Forest Temp (C): ${temp2.toFixed(2)}`);

    if (temp1 < temp2) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("Authentication or Initialization failed:", e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
